Here's a modern MSTest approach for testing your `DataFetcher`:

```csharp
[TestClass]
public sealed class DataFetcherTests
{
    [TestMethod]
    public async Task FetchAsync_ReturnsContent_WhenRequestSucceeds()
    {
        var handler = new MockHttpMessageHandler("expected content", HttpStatusCode.OK);
        using var client = new HttpClient(handler);
        var fetcher = new DataFetcher(client);

        string result = await fetcher.FetchAsync("https://example.com");

        Assert.AreEqual("expected content", result);
    }

    [TestMethod]
    public async Task FetchAsync_Throws_WhenResponseIsError()
    {
        var handler = new MockHttpMessageHandler("", HttpStatusCode.InternalServerError);
        using var client = new HttpClient(handler);
        var fetcher = new DataFetcher(client);

        await Assert.ThrowsExactlyAsync<HttpRequestException>(
            () => fetcher.FetchAsync("https://example.com"));
    }

    [TestMethod]
    public async Task FetchAsync_ThrowsOperationCanceled_WhenTokenCancelled()
    {
        var handler = new MockHttpMessageHandler("content", HttpStatusCode.OK, delay: TimeSpan.FromSeconds(5));
        using var client = new HttpClient(handler);
        using var cts = new CancellationTokenSource();
        var fetcher = new DataFetcher(client);

        cts.Cancel();

        await Assert.ThrowsExactlyAsync<TaskCanceledException>(
            () => fetcher.FetchAsync("https://example.com", cts.Token));
    }

    [TestMethod]
    [Timeout(5000)] // Safety net — fails if test hangs
    public async Task FetchAsync_CompletesWithinTimeout()
    {
        var handler = new MockHttpMessageHandler("fast", HttpStatusCode.OK);
        using var client = new HttpClient(handler);
        var fetcher = new DataFetcher(client);

        string result = await fetcher.FetchAsync("https://example.com", TestContext.CancellationTokenSource.Token);

        Assert.AreEqual("fast", result);
    }

    public TestContext TestContext { get; set; } = null!;

    // Reusable mock handler
    private sealed class MockHttpMessageHandler(string content, HttpStatusCode statusCode, TimeSpan? delay = null)
        : HttpMessageHandler
    {
        protected override async Task<HttpResponseMessage> SendAsync(
            HttpRequestMessage request, CancellationToken cancellationToken)
        {
            if (delay.HasValue)
                await Task.Delay(delay.Value, cancellationToken);

            return new HttpResponseMessage(statusCode)
            {
                Content = new StringContent(content)
            };
        }
    }
}
```

**Key modern MSTest patterns used:**

| Pattern | Detail |
|---------|--------|
| `async Task` test methods | MSTest natively awaits them — no `GetAwaiter().GetResult()` needed |
| `Assert.ThrowsExactlyAsync` | MSTest v3+ preferred over `ThrowsExceptionAsync` (exact type match) |
| `[Timeout(ms)]` | Per-test safety net; kills hung tests |
| `TestContext.CancellationTokenSource.Token` | MSTest-managed token that fires when `[Timeout]` expires — propagate it into your SUT to get cooperative cancellation |
| Custom `HttpMessageHandler` | Avoids mocking framework dependency; gives full control over responses and delays |

**Tips:**
- Always pass `CancellationToken` through to the SUT in timeout-guarded tests so the timeout actually cancels the operation rather than just abandoning it.
- `[Timeout]` applies to the entire test method including setup. Use `[AssemblyInitialize]` or `[ClassInitialize]` timeouts separately if init is slow.
- In MSTest v3+, prefer `ThrowsExactlyAsync` over `ThrowsExceptionAsync` — the latter also matches derived exception types.
